import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())

attach_template = '''
#### ATTACH BEGIN #######
forw mte setUeContext {ue_id}
forw mte UsimConfig 1([{imsi} 3] [] [] [] []) [] [] [01020304050607080910101010101001] \
[63BFA50EE6523365FF14C1F45F88737D 00000000000000000000000000000000 00000000000000000000000000000001 \
00000000000000000000000000000002 00000000000000000000000000000004 00000000000000000000000000000008 \
64 0 32 64 96 []] [] []
forw mte RrcAptConfigUeCap [[] [] [] [] [] [] \
[3{{0 DDB802800048900048002400120009000480024001200090004801FC1BB13000C00611200000000A952\
40111400000000590008E1B400304800002A10040890001304800000A480001000008250500500400,\
5 8000038020084000000400040160C01D00000000,6
1108040100DD00000001600040800008000000400004000000}}]]
forw mte Activate -1
WAIT FOR "ACTIVATE" TIMEOUT 5

forw mte PhyConfigSysCap 2 4 4
forw mte NrPhyConfigSysCap
forw mte RrcAptConfigCellSelection 26250
forw mte NasAptConfigPlmnSelection 311489
forw mte NasAptConfigCapability [3] [128] [128]

# for 5G cells
FORW L2 SETRADIOCONTEXT 1
FORW L1 SETRADIOCONTEXT 1
FORW L1 SETRFRXGAIN 0 -40

FORW L1 NRSETPATHDELAY 56

forw mte NasConfigEmmRegister {pdn_id}
forw mte Activate -1
WAIT FOR "ACTIVATE" TIMEOUT {timeout}
#### ATTACH END #######
'''


class AttachScript5G(object):
    """TMA script for attaching a single UE to a 5G cell."""

    def __init__(self, ue_id, imsi, pdn_id, timeout=5):
        self.ue_id = ue_id
        self.imsi = imsi
        self.pdn_id = pdn_id
        self.timeout = timeout

    def __str__(self):
        return attach_template.format(ue_id=self.ue_id,
                                      imsi=self.imsi,
                                      pdn_id=self.pdn_id,
                                      timeout=self.timeout)

    def __add__(self, other):
        return str(self) + str(other)

    def __radd__(self, other):
        return str(other) + str(self)
